char **computeSimilarities(int **docs, int docsSize, int *docsColSize, int *returnSize) {
  char **res = (char **)malloc(sizeof(char *) * (docsSize * docsSize + 1));
  *returnSize = 0;
  for (int i = 0; i < docsSize; i++) {
    for (int j = i + 1; j < docsSize; j++) {
      int inter = 0;
      for (int a = 0; a < docsColSize[i]; a++) {
        for (int b = 0; b < docsColSize[j]; b++) {
          if (docs[i][a] == docs[j][b]) {
            inter++;
            break;
          }
        }
      }
      if (inter > 0) {
        int uni = docsColSize[i] + docsColSize[j] - inter;
        char *s = (char *)malloc(64);
        sprintf(s, "%d,%d: %.4f", i, j, (double)inter / uni);
        res[(*returnSize)++] = s;
      }
    }
  }
  return res;
}

class Solution {
public:
  vector<string> computeSimilarities(vector<vector<int>> &docs) {
    unordered_map<int, vector<int>> wordDocs;
    for (int i = 0; i < (int)docs.size(); i++) {
      for (int w : docs[i]) wordDocs[w].push_back(i);
    }
    map<pair<int, int>, int> inter;
    for (auto &kv : wordDocs) {
      auto &ids = kv.second;
      for (size_t a = 0; a < ids.size(); a++) {
        for (size_t b = a + 1; b < ids.size(); b++) {
          inter[{ids[a], ids[b]}]++;
        }
      }
    }
    vector<string> res;
    for (auto &kv : inter) {
      int i = kv.first.first, j = kv.first.second;
      int c = kv.second;
      int uni = docs[i].size() + docs[j].size() - c;
      ostringstream oss;
      oss << i << "," << j << ": " << fixed << setprecision(4) << (double)c / uni;
      res.push_back(oss.str());
    }
    return res;
  }
};

func computeSimilarities(docs [][]int) []string {
	wordDocs := map[int][]int{}
	for i, doc := range docs {
		for _, w := range doc {
			wordDocs[w] = append(wordDocs[w], i)
		}
	}
	type key struct{ a, b int }
	inter := map[key]int{}
	for _, ids := range wordDocs {
		for x := 0; x < len(ids); x++ {
			for y := x + 1; y < len(ids); y++ {
				inter[key{ids[x], ids[y]}]++
			}
		}
	}
	keys := []key{}
	for k := range inter {
		keys = append(keys, k)
	}
	sort.Slice(keys, func(i, j int) bool {
		if keys[i].a != keys[j].a {
			return keys[i].a < keys[j].a
		}
		return keys[i].b < keys[j].b
	})
	res := []string{}
	for _, k := range keys {
		c := inter[k]
		uni := len(docs[k.a]) + len(docs[k.b]) - c
		res = append(res, fmt.Sprintf("%d,%d: %.4f", k.a, k.b, float64(c)/float64(uni)))
	}
	return res
}

class Solution {
  public List<String> computeSimilarities(int[][] docs) {
    Map<Integer, List<Integer>> wordDocs = new HashMap<>();
    for (int i = 0; i < docs.length; i++) {
      for (int w : docs[i]) wordDocs.computeIfAbsent(w, k -> new ArrayList<>()).add(i);
    }
    Map<String, Integer> inter = new TreeMap<>();
    for (List<Integer> ids : wordDocs.values()) {
      for (int a = 0; a < ids.size(); a++) {
        for (int b = a + 1; b < ids.size(); b++) {
          int i = ids.get(a), j = ids.get(b);
          String key = String.format("%05d,%05d", i, j);
          inter.put(key, inter.getOrDefault(key, 0) + 1);
        }
      }
    }
    List<String> res = new ArrayList<>();
    for (Map.Entry<String, Integer> e : inter.entrySet()) {
      String[] parts = e.getKey().split(",");
      int i = Integer.parseInt(parts[0]), j = Integer.parseInt(parts[1]);
      int c = e.getValue();
      int uni = docs[i].length + docs[j].length - c;
      res.add(String.format("%d,%d: %.4f", i, j, (double) c / uni));
    }
    return res;
  }
}

class Solution:
    def computeSimilarities(self, docs: List[List[int]]) -> List[str]:
        word_docs = defaultdict(list)
        for i, doc in enumerate(docs):
            for w in doc:
                word_docs[w].append(i)
        inter = defaultdict(int)
        for ids in word_docs.values():
            for a in range(len(ids)):
                for b in range(a + 1, len(ids)):
                    inter[(ids[a], ids[b])] += 1
        res = []
        for (i, j) in sorted(inter):
            c = inter[(i, j)]
            uni = len(docs[i]) + len(docs[j]) - c
            res.append("{},{}: {:.4f}".format(i, j, c / uni))
        return res

impl Solution {
  pub fn compute_similarities(docs: Vec<Vec<i32>>) -> Vec<String> {
    let mut word_docs: HashMap<i32, Vec<usize>> = HashMap::new();
    for (i, doc) in docs.iter().enumerate() {
      for &w in doc {
        word_docs.entry(w).or_insert_with(Vec::new).push(i);
      }
    }
    let mut inter: HashMap<(usize, usize), i32> = HashMap::new();
    for ids in word_docs.values() {
      for a in 0..ids.len() {
        for b in a + 1..ids.len() {
          *inter.entry((ids[a], ids[b])).or_insert(0) += 1;
        }
      }
    }
    let mut pairs: Vec<((usize, usize), i32)> = inter.into_iter().collect();
    pairs.sort_by_key(|(k, _)| *k);
    pairs
      .into_iter()
      .map(|((i, j), c)| {
        let uni = (docs[i].len() + docs[j].len()) as f64 - c as f64;
        format!("{},{}: {:.4}", i, j, c as f64 / uni)
      })
      .collect()
  }
}

const computeSimilarities = (docs: number[][]): string[] => {
  const wordDocs = new Map<number, number[]>();
  for (let i = 0; i < docs.length; i++) {
    for (const w of docs[i]) {
      if (!wordDocs.has(w)) wordDocs.set(w, []);
      wordDocs.get(w)!.push(i);
    }
  }
  const inter = new Map<string, number>();
  for (const ids of wordDocs.values()) {
    for (let a = 0; a < ids.length; a++) {
      for (let b = a + 1; b < ids.length; b++) {
        const key = `${ids[a]},${ids[b]}`;
        inter.set(key, (inter.get(key) ?? 0) + 1);
      }
    }
  }
  const keys = [...inter.keys()].sort((x, y) => {
    const [a1, b1] = x.split(',').map(Number);
    const [a2, b2] = y.split(',').map(Number);
    return a1 - a2 || b1 - b2;
  });
  return keys.map((key) => {
    const [i, j] = key.split(',').map(Number);
    const c = inter.get(key)!;
    const uni = docs[i].length + docs[j].length - c;
    return `${i},${j}: ${(c / uni).toFixed(4)}`;
  });
};
